}

for ($index = 0; $index -lt $expected.Count; $index++) {
    if ($changed[$index] -cne $expected[$index]) {
        throw "Inventario BL-MVP-061 no coincide. Esperado '$($expected[$index])', encontrado '$($changed[$index])'."
    }
}

